<template><section class="page-content pos-page"><div class="page-heading"><div><p class="eyebrow">TRANSAKSI PENJUALAN</p><h1>POS</h1><p class="page-description">Catat penjualan, kelola pembayaran, dan kurangi stok saat transaksi dikunci.</p></div><button class="button button-primary" type="button" @click="router.push('/pos/baru')">+ Transaksi Baru</button></div><section class="panel"><div class="panel-header"><div><h2>Daftar Penjualan</h2><p>{{ transactions.length }} transaksi tercatat</p></div></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Pelanggan</th><th>Pembayaran</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="tx in transactions" :key="tx.id"><td>{{ tx.nomor }}</td><td>{{ formatDate(tx.tanggal) }}</td><td>{{ tx.pelangganNama || 'Umum' }}</td><td>{{ tx.metodePembayaran.toUpperCase() }}</td><td>{{ formatRupiah(tx.total) }}</td><td><span :class="['status-badge', tx.status === 'locked' ? 'status-locked' : 'status-draft']">{{ tx.status === 'locked' ? 'Terkunci' : 'Draft' }}</span></td><td><button class="table-action" type="button" @click="router.push(tx.status === 'locked' ? `/pos/${tx.id}` : `/pos/${tx.id}/edit`)">{{ tx.status === 'locked' ? 'Detail' : 'Edit' }}</button></td></tr><tr v-if="!transactions.length"><td colspan="7" class="empty-cell">Belum ada transaksi penjualan.</td></tr></tbody></table></div></section></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { collection, getDocs } from 'firebase/firestore'; import { useRouter } from 'vue-router'; import { db } from '@/firebase'; import { authState } from '@/auth'; const router = useRouter(); const transactions = ref<any[]>([]); const basePath = () => `warungs/${authState.warungId}`; const formatRupiah = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0); const formatDate = (value: string) => value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium' }).format(new Date(value)) : '-'; const load = async () => { if (!authState.warungId) return; const snapshot = await getDocs(collection(db, basePath(), 'sales')); transactions.value = snapshot.docs.map((item) => ({ id: item.id, ...item.data() })) }; onMounted(load);
</script>
